Script.parameter:
if(work["$idmlBook"] != null) {
	task.logmsg("*** The IdML book has been closed.");
	task.logmsg("*** The accumulated in-memory snippet is:");
	task.logmsg(work["$idmlBook"]);
}

Hook.Script:
if(work["$idmlFileName"] != null) {
	task.logmsg("*** IdML book has been split");
	task.logmsg("*** File: '" + work["$idmlFileName"] + "' has been closed.'");
	task.logmsg("***")
}
